function confirm({records,fields}){if(!Array.isArray(records)||records.length!==1||typeof records[0]?.id!=='string'||!records[0].id)throw Error('Airtable did not confirm one record');const f=records[0].fields;if(!f||f.Score!==fields.Score||f.Name!==fields.Name||(f.Email??'')!==fields.Email||(f.Description??'')!==fields.Description)throw Error('Airtable record differs from submitted feedback');const name=`[${f.Score}] ${f.Name}`,description=`Name: ${f.Name}
Email: ${f.Email??''}
Score: ${f.Score}
Description: ${f.Description??''}`;return {low:f.Score<7,name,description}}

const items=$input.all();return [{json:confirm({records:items.map(x=>x.json),fields:$("Read the feedback answers").first().json})}];
